# Game#z_movement
def dc_st_kp_z_movement(gx, mobj_ceilingz, mobj_flags, mobj_floorz, mobj_height, mobj_momz, mobj_player,
                        mobj_target, mobj_x, mobj_y, mobj_z, state, ks, ks_n, fb)
  pc = ks[fb + 1]
  while true
    if pc <= 6
      if pc <= 2
        if pc <= 0
            ks[fb + 3] = mobj_player[ks[fb + 2]] >= 0 ? 1 : 0
            if ks[fb + 3] != 0 && mobj_z[ks[fb + 2]] < mobj_floorz[ks[fb + 2]]
              state[gx[G_PL_VIEWHEIGHT]] = core_w32_sub(state[gx[G_PL_VIEWHEIGHT]], core_w32_sub(mobj_floorz[ks[fb + 2]], mobj_z[ks[fb + 2]]))
              state[gx[G_PL_DELTAVIEWHEIGHT]] = core_w32_sub(SP_VIEWHEIGHT, state[gx[G_PL_VIEWHEIGHT]]) >> 3
            end
            0
            mobj_z[ks[fb + 2]] = core_w32_add(mobj_z[ks[fb + 2]], mobj_momz[ks[fb + 2]])
            if (mobj_flags[ks[fb + 2]] & SP_MF_FLOAT) != 0 && mobj_target[ks[fb + 2]] >= 0
              if (mobj_flags[ks[fb + 2]] & SP_MF_SKULLFLY) == 0 && (mobj_flags[ks[fb + 2]] & SP_MF_INFLOAT) == 0
                ks[fb + 4] = mobj_target[ks[fb + 2]]
                ks[fb + 5] = dc_st_aprox_distance(core_w32_sub(mobj_x[ks[fb + 2]], mobj_x[ks[fb + 4]]), core_w32_sub(mobj_y[ks[fb + 2]], mobj_y[ks[fb + 4]]))
                ks[fb + 6] = core_w32_sub(core_w32_add(mobj_z[ks[fb + 4]], (mobj_height[ks[fb + 2]] >> 1)), mobj_z[ks[fb + 2]])
                if ks[fb + 6] < 0 && ks[fb + 5] < -(ks[fb + 6] * 3)
                  mobj_z[ks[fb + 2]] = core_w32_sub(mobj_z[ks[fb + 2]], SP_FLOATSPEED)
                elsif ks[fb + 6] > 0 && ks[fb + 5] < ks[fb + 6] * 3
                  mobj_z[ks[fb + 2]] = core_w32_add(mobj_z[ks[fb + 2]], SP_FLOATSPEED)
                end
                0
              end
              0
            end
            0
            if mobj_z[ks[fb + 2]] <= mobj_floorz[ks[fb + 2]]
              pc = 1
            else
              pc = 2
            end
            0

        else
          if pc <= 1
              if (mobj_flags[ks[fb + 2]] & SP_MF_SKULLFLY) != 0
                mobj_momz[ks[fb + 2]] = core_w32_neg(mobj_momz[ks[fb + 2]])
              end
              0
              if mobj_momz[ks[fb + 2]] < 0
                if ks[fb + 3] != 0 && mobj_momz[ks[fb + 2]] < -SP_GRAVITY * 8
                  state[gx[G_PL_DELTAVIEWHEIGHT]] = mobj_momz[ks[fb + 2]] >> 3
                end
                0
                mobj_momz[ks[fb + 2]] = 0
              end
              0
              mobj_z[ks[fb + 2]] = mobj_floorz[ks[fb + 2]]
              if (mobj_flags[ks[fb + 2]] & SP_MF_MISSILE) != 0 && (mobj_flags[ks[fb + 2]] & SP_MF_NOCLIP) == 0
                pc = 4
              else
                pc = 5
              end
              0

          else
              if (mobj_flags[ks[fb + 2]] & SP_MF_NOGRAVITY) == 0
                if mobj_momz[ks[fb + 2]] == 0
                  mobj_momz[ks[fb + 2]] = -SP_GRAVITY * 2
                else
                  mobj_momz[ks[fb + 2]] = core_w32_sub(mobj_momz[ks[fb + 2]], SP_GRAVITY)
                end
                0
              end
              0
              pc = 3
              0

          end
        end
      else
        if pc <= 4
          if pc <= 3
              if core_w32_add(mobj_z[ks[fb + 2]], mobj_height[ks[fb + 2]]) > mobj_ceilingz[ks[fb + 2]]
                pc = 8
              else
                pc = 9
              end
              0

          else
              if fb + 42 > ks_n
                core_fail(:capacity)
              end
              ks[fb + 21] = 43
              ks[fb + 22] = 0
              ks[fb + 23] = ks[fb + 2]
              ks[fb + 1] = 7
              return 1

          end
        else
          if pc <= 5
              pc = 6
              0

          else
              pc = 3
              0

          end
        end
      end
    else
      if pc <= 10
        if pc <= 8
          if pc <= 7
              ks[0] = 0
              return 0
              pc = 6
              0

          else
              if mobj_momz[ks[fb + 2]] > 0
                mobj_momz[ks[fb + 2]] = 0
              end
              0
              mobj_z[ks[fb + 2]] = core_w32_sub(mobj_ceilingz[ks[fb + 2]], mobj_height[ks[fb + 2]])
              if (mobj_flags[ks[fb + 2]] & SP_MF_SKULLFLY) != 0
                mobj_momz[ks[fb + 2]] = core_w32_neg(mobj_momz[ks[fb + 2]])
              end
              0
              if (mobj_flags[ks[fb + 2]] & SP_MF_MISSILE) != 0 && (mobj_flags[ks[fb + 2]] & SP_MF_NOCLIP) == 0
                pc = 11
              else
                pc = 12
              end
              0

          end
        else
          if pc <= 9
              pc = 10
              0

          else
              0
              ks[0] = 0
              return 0

          end
        end
      else
        if pc <= 12
          if pc <= 11
              if fb + 42 > ks_n
                core_fail(:capacity)
              end
              ks[fb + 21] = 43
              ks[fb + 22] = 0
              ks[fb + 23] = ks[fb + 2]
              ks[fb + 1] = 14
              return 1

          else
              pc = 13
              0

          end
        else
          if pc <= 13
              pc = 10
              0

          else
              pc = 13
              0

          end
        end
      end
    end
  end
  0
end

